def can_distribute_candies(a, b, c):
    total = a + b + c
    if total % 2 != 0:
        return "No"
    target = total // 2
    if target >= a and target >= b and target >= c:
        return "Yes"
    elif target >= a and target >= (b + c):
        return "Yes"
    elif target >= b and target >= (a + c):
        return "Yes"
    elif target >= c and target >= (a + b):
        return "Yes"
    else:
        return "No"

import sys
input = sys.stdin.read
data = input().split()
a = int(data[0])
b = int(data[1])
c = int(data[2])

print(can_distribute_candies(a, b, c))
